    args = parser.parse_args()

files = iter_metadata_files([Path(value) for value in args.paths])
    if not files:
        return emit_result(
            ["HIGH no profile, permission set, or permission set group metadata files found"],
            "Scanned 0 access-model metadata file(s); no files matched the provided paths.",
        )

findings: list[str] = []
    for path in files:
        findings.extend(audit_file(path))

summary = f"Scanned {len(files)} access-model metadata file(s); {len(findings)} finding(s) detected."
    return emit_result(findings, summary)

if __name__ == "__main__":
    sys.exit(main())

# Salesforce platform limits
PICKLIST_MAX_VALUES = 1000        # standard and custom picklist (active + inactive)
MULTISELECT_MAX_VALUES = 500      # multi-select picklist active values
EMPTY_FIELD_WARN_THRESHOLD = 0    # warn if a picklist has zero values

SF_NAMESPACE = "http://soap.sforce.com/2006/04/metadata"

def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description=(
            "Check Salesforce metadata for common picklist anti-patterns. "
            "Expects sfdx source-format layout: objects/<ObjectName>/<ObjectName>.object-meta.xml "
            "or fields/<FieldName>.field-meta.xml files."
        ),
    )
    parser.add_argument(
        "--manifest-dir",
        default=".",
        help="Root directory of the Salesforce SFDX project (default: current directory).",
    )
    return parser.parse_args()

def _ns(tag: str) -> str:
    """Prepend Salesforce metadata namespace to a tag name."""
    return f"{{{SF_NAMESPACE}}}{tag}"

def _find_field_files(manifest_dir: Path) -> list[Path]:
    """Find all .field-meta.xml files in the project."""
    return list(manifest_dir.rglob("*.field-meta.xml"))

def check_picklist_and_value_sets(manifest_dir: Path) -> list[str]:
    """Return a list of issue strings found in the manifest directory."""
    issues: list[str] = []

if not manifest_dir.exists():
        issues.append(f"Manifest directory not found: {manifest_dir}")
        return issues

field_files = _find_field_files(manifest_dir)

if not field_files:
        # No field files found — may not be an sfdx project, skip silently
        return issues

# Track (object_name → {sorted_labels_tuple → [field_names]}) for duplication check
    object_value_map: dict[str, dict[tuple[str, ...], list[str]]] = {}

for field_path in field_files:
        try:
            tree = ET.parse(field_path)
        except ET.ParseError as exc:
            issues.append(f"XML parse error in {field_path}: {exc}")
            continue

root = tree.getroot()
        field_type, labels, is_multi, uses_gvs = _parse_picklist_values(root)

if field_type not in ("Picklist", "MultiselectPicklist"):
            continue

# Check 2: exceeds platform limits
        value_count = len(labels)
        if is_multi and value_count > MULTISELECT_MAX_VALUES:
            issues.append(
                f"{field_id}: Multi-select picklist has {value_count} values, "
                f"exceeding the platform limit of {MULTISELECT_MAX_VALUES}. "
                "Reduce active values or reconsider field design."
            )
        elif not is_multi and value_count > PICKLIST_MAX_VALUES:
            issues.append(
                f"{field_id}: Picklist has {value_count} values (active + inactive), "
                f"exceeding the platform limit of {PICKLIST_MAX_VALUES}."
            )

# Check 3: collect for duplication heuristic (only for inline value sets)
        if labels and not uses_gvs:
            sorted_key = tuple(sorted(labels))
            if object_name not in object_value_map:
                object_value_map[object_name] = {}
            bucket = object_value_map[object_name].setdefault(sorted_key, [])
            bucket.append(field_name)

# Check 3 (continued): flag objects with 2+ picklist fields sharing identical value lists
    for obj_name, value_buckets in object_value_map.items():
        for value_key, field_names in value_buckets.items():
            if len(field_names) >= 2 and len(value_key) >= 2:
                issues.append(
                    f"{obj_name}: Fields {field_names} share identical picklist values "
                    f"({len(value_key)} values) without using a Global Value Set. "
                    "Consider using a Global Value Set to manage shared values centrally."
                )

return issues

def main() -> int:
    args = parse_args()
    manifest_dir = Path(args.manifest_dir)
    issues = check_picklist_and_value_sets(manifest_dir)

if not issues:
        print("No picklist issues found.")
        return 0

for issue in issues:
        print(f"ISSUE: {issue}")

return 1

if __name__ == "__main__":
    sys.exit(main())

def normalize_finding(finding: str) -> dict[str, str]:
    severity, _, remainder = finding.partition(" ")
    location = ""
    message = remainder
    if ": " in remainder:
        location, message = remainder.split(": ", 1)
    return {"severity": severity or "INFO", "location": location, "message": message}

def emit_result(findings: list[str], summary: str) -> int:
    normalized = [normalize_finding(item) for item in findings]
    score = max(0, 100 - sum(SEVERITY_WEIGHTS.get(item["severity"], 0) for item in normalized))
    print(json.dumps({"score": score, "findings": normalized, "summary": summary}, indent=2))
    return 1 if normalized else 0

def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8", errors="ignore")

def main() -> int:
    args = parse_args()
    root = Path(args.manifest_dir)
    if not root.exists():
        return emit_result([f"HIGH {root}: manifest directory not found"], "Scanned 0 files; manifest directory was missing.")

findings: list[str] = []
    object_flows: dict[str, int] = defaultdict(int)
    object_triggers: dict[str, int] = defaultdict(int)

workflow_files = sorted(root.rglob("*.workflow-meta.xml"))
    if workflow_files:
        findings.append(f"REVIEW {root}: {len(workflow_files)} Workflow Rule metadata file(s) found; treat them as migration inventory, not ongoing design")

for path in sorted(root.rglob("*.flow-meta.xml")):
        text = read_text(path)
        object_match = FLOW_OBJECT_RE.search(text)
        if object_match:
            object_flows[object_match.group(1)] += 1
        process_type = PROCESS_TYPE_RE.search(text)
        if process_type and process_type.group(1).lower() == "workflow":
            findings.append(f"REVIEW {path}: legacy workflow-style Flow metadata found; verify this is migration scope and not an active architecture choice")

for path in sorted(root.rglob("*.trigger")):
        text = read_text(path)
        object_match = TRIGGER_RE.search(text)
        if object_match:
            object_triggers[object_match.group(1)] += 1

for object_name in sorted(set(object_flows) | set(object_triggers)):
        flow_count = object_flows.get(object_name, 0)
        trigger_count = object_triggers.get(object_name, 0)
        if flow_count >= 3:
            findings.append(f"REVIEW {root}: {flow_count} Flow metadata files found for object {object_name}; confirm automation ownership is still clear")
        if flow_count > 0 and trigger_count > 0:
            findings.append(f"REVIEW {root}: object {object_name} has both Flow and Apex trigger automation; verify the tool boundary is intentional and documented")

scanned = len(workflow_files) + len(list(root.rglob('*.flow-meta.xml'))) + len(list(root.rglob('*.trigger')))
    if scanned == 0:
        return emit_result([f"HIGH {root}: no Flow, Workflow Rule, or trigger metadata found"], "Scanned 0 automation files.")

summary = f"Scanned {scanned} automation file(s); {len(findings)} selection-boundary finding(s) detected."
    return emit_result(findings, summary)

if __name__ == "__main__":
    sys.exit(main())

